// Vue 3 Todo 应用核心代码框架
// stores/todo.ts
export const useTodoStore = defineStore('todo', () => {
  const todos = ref(JSON.parse(localStorage.getItem('todos') || '[]'))
  const filter = ref('all') // 'all' | 'active' | 'completed'

  const filteredTodos = computed(() => {
    if (filter.value === 'active') return todos.value.filter(t => !t.done)
    if (filter.value === 'completed') return todos.value.filter(t => t.done)
    return todos.value
  })

  function addTodo(text) {
    todos.value.push({ id: Date.now(), text, done: false })
    save()
  }

  function toggleTodo(id) {
    const todo = todos.value.find(t => t.id === id)
    if (todo) todo.done = !todo.done
    save()
  }

  function removeTodo(id) {
    todos.value = todos.value.filter(t => t.id !== id)
    save()
  }

  function save() {
    localStorage.setItem('todos', JSON.stringify(todos.value))
  }

  return { todos, filter, filteredTodos, addTodo, toggleTodo, removeTodo }
})

// server.js — Express REST API
const express = require('express')
const app = express()
app.use(express.json())

// 模拟数据库
let books = [
  { id: 1, title: 'JavaScript高级程序设计', author: 'Nicholas' },
  { id: 2, title: 'CSS权威指南', author: 'Eric Meyer' }
]
let nextId = 3

// GET — 获取所有书籍
app.get('/api/books', (req, res) => {
  res.json(books)
})

// GET — 获取单本书
app.get('/api/books/:id', (req, res) => {
  const book = books.find(b => b.id === +req.params.id)
  book ? res.json(book) : res.status(404).json({ error: 'Not Found' })
})

// POST — 创建新书
app.post('/api/books', (req, res) => {
  const book = { id: nextId++, ...req.body }
  books.push(book)
  res.status(201).json(book)
})

// PUT — 更新书籍
app.put('/api/books/:id', (req, res) => {
  const idx = books.findIndex(b => b.id === +req.params.id)
  if (idx === -1) return res.status(404).json({ error: 'Not Found' })
  books[idx] = { ...books[idx], ...req.body }
  res.json(books[idx])
})

// DELETE — 删除书籍
app.delete('/api/books/:id', (req, res) => {
  books = books.filter(b => b.id !== +req.params.id)
  res.status(204).send()
})

app.listen(3000, () => console.log('🚀 API Server → http://localhost:3000'))
